-- Retrieve IDs of experiments older than two years and those not older than two years for indexing.
WITH archived AS (
    SELECT experiment_id FROM experiments WHERE created_at < date('now', '-2 years')
), excluded AS (
    SELECT experiment_id FROM experiments WHERE created_at >= date('now', '-2 years')
)
SELECT 'Archived IDs' AS category, experiment_id FROM archived
UNION ALL
SELECT 'Excluded IDs' AS category, experiment_id FROM excluded;

